from fastapi import Request

class MyException(Exception):
    pass

@app.exception_handler(MyException)
async def my_exception_handler(request: Request, exc: MyException):
    return JSONResponse(status_code=418, content={"detail": "Custom error"})

from fastapi import Request

@app.get("/ip")
async def get_ip(request: Request):
    client_host = request.client.host
    return {"ip": client_host}

def dependency(param: str):
    def inner():
        return f"Hello {param}"
    return Depends(inner)

@app.get("/")
async def home(dep=dependency("World")):
    return {"msg": dep}

from slowapi import Limiter
from slowapi.util import get_remote_address

limiter = Limiter(key_func=get_remote_address)
app.state.limiter = limiter
app.add_middleware(SlowAPIMiddleware)

@app.get("/")
@limiter.limit("5/minute")
async def index():
    return {"msg": "Hello"}

from fastapi import Query

@app.get("/items")
async def read_items(q: str = Query(...), limit: int = Query(10)):
    return {"q": q, "limit": limit}

from pydantic import constr

class User(BaseModel):
    username: constr(max_length=20)

from fastapi import Form, UploadFile, File

@app.post("/submit")
async def submit(name: str = Form(...), file: UploadFile = File(...)):
    contents = await file.read()
    return {"name": name, "filename": file.filename}

from typing import List
from fastapi import Query

@app.get("/numbers")
async def get_numbers(nums: List[int] = Query(...)):
    return {"nums": nums}

class Item(BaseModel):
    name: str

@app.post("/items", response_model=Item)
async def create_item(item: Item):
    return item

app.schema_extra = {
