from fastapi.responses import StreamingResponse

@app.post("/stream")
async def stream():
    def iterfile():
        yield b"hello"
    return StreamingResponse(iterfile())

from fastapi.responses import JSONResponse

@app.get("/conditional-header")
async def conditional_header(flag: bool):
    headers = {"X-Flag": "true"} if flag else {}
    return JSONResponse(content={"msg": "ok"}, headers=headers)

from enum import Enum

class Status(str, Enum):
    active = "active"
    inactive = "inactive"

@app.get("/status")
async def get_status(status: Status):
    return {"status": status}

from fastapi import Header

@app.get("/custom-header")
async def custom_header(x_token: str = Header(...)):
    return {"X-Token": x_token}

from fastapi.responses import RedirectResponse

@app.get("/old")
async def redirect():
    return RedirectResponse(url="/new")
